// Global auto-close notification infrastructure
if (typeof window !== 'undefined') {
  if (!window.tbAutoCloseObserverAttached) {
    window.tbAutoCloseObserverAttached = true;
    var tbToastObserver = new MutationObserver(function() {
      var toasts = document.querySelectorAll('tb-snack-bar-component');
      for (var i = 0; i < toasts.length; i++) {
        var t = toasts[i];
        if (!t.getAttribute('data-autoclose-armed')) {
          t.setAttribute('data-autoclose-armed', '1');
          setTimeout(function() {
            var btn = t.querySelector('button');
            if (btn) { btn.click(); }
            else if (t.parentNode) { t.parentNode.removeChild(t); }
          }, 5000);
        }
      }
    });
    tbToastObserver.observe(document.body, { childList: true, subtree: true });
  }

  var curCtx = (typeof widgetContext !== 'undefined' ? widgetContext : (this && this.ctx ? this.ctx : null));
  if (curCtx && curCtx.constructor && curCtx.constructor.prototype && !curCtx.constructor.prototype.__autoclose_patched) {
    curCtx.constructor.prototype.__autoclose_patched = true;
    var _origShowErrorToast = curCtx.constructor.prototype.showErrorToast;
    curCtx.constructor.prototype.showErrorToast = function(msg, vPos, hPos, target, forceDismiss) {
      if (this.showToast) {
        this.showToast('error', msg, 5000, vPos || 'top', hPos || 'right', target || 'dashboardRoot', forceDismiss);
      } else if (_origShowErrorToast) {
        _origShowErrorToast.call(this, msg, vPos, hPos, target, forceDismiss);
      }
    };
  }
}

return '<div class="card-layout flex flex-row">' +
            '<tb-dashboard-state [ctx]="ctx" [syncParentStateParams]="true" stateId="frame" class="farme-state flex-1"></tb-dashboard-state>' +
            '<tb-dashboard-state [ctx]="ctx" [syncParentStateParams]="true" stateId="aqi_section" class="aqi-section-state"></tb-dashboard-state>' +
        '</div>';

