// Mirror of the map marker's own deselect branch: this dashboard selects with
// params.entityId / params.entityName, so clearing the selection means deleting
// exactly those two keys. (The template shipped `params['selectedSensor'] = null`
// -- a key nothing here reads, which is why this button did nothing.)
var params = widgetContext.stateController.getStateParams() || {};
var newParams = Object.assign({}, params);
delete newParams.entityId;
delete newParams.entityName;
widgetContext.stateController.updateState(null, newParams);

