tooltip.patternFunction:
// Gateway position (device 'Gateway' server attributes - Yaounde)
var gwLat = 3.8580443501700916;
var gwLng = 11.499728634735224;

function num(v) { return v !== undefined && v !== null && v !== '' ? parseFloat(v) : null; }
// two firmware variants write the same metric under different keys; a literal 0
// is a known disconnected-sensor artifact, so prefer whichever reading is non-zero
var lat = num(data.latitude);
var lng = num(data.longitude);
var distanceStr = 'N/A';
if (lat !== null && lng !== null) {
    var R = 6371;
    var dLat = (lat - gwLat) * Math.PI / 180;
    var dLng = (lng - gwLng) * Math.PI / 180;
    var a = Math.sin(dLat/2) * Math.sin(dLat/2) +
            Math.cos(gwLat * Math.PI / 180) * Math.cos(lat * Math.PI / 180) *
            Math.sin(dLng/2) * Math.sin(dLng/2);
    var d = 6371 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a)) * 1000;
    distanceStr = d < 1000 ? d.toFixed(0) + ' m' : (d/1000).toFixed(2) + ' km';
}

var temp = num(data.temperature);
var hum  = num(data.humidity);
var co   = num(data.co_ppm);
