  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  min-height: clamp(18px, 1.2vw, 22px);
  flex: 0 0 auto;
}
.kpi-title {
  font-size: clamp(13px, 0.85vw, 16px);
  font-weight: 500;
  color: rgba(0, 0, 0, 0.6);
  letter-spacing: 0.15px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi-pill {
  font-size: clamp(10px, 0.6vw, 11px);
  font-weight: 700;
  letter-spacing: 0.5px;
  padding: 2px clamp(6px, 0.5vw, 8px);
  border-radius: var(--tb-badge-radius, 9999px);
  flex: 0 0 auto;
}
.kpi-pill.ok { background: rgba(30,108,51,.12); color: var(--tb-ok, #1E6C33); }
.kpi-pill.fault { background: rgba(179,38,30,.12); color: var(--tb-danger, #B3261E); }
.kpi-pill.masked { background: rgba(0,0,0,.07); color: #9E9E9E; }
