  flex-direction: column;
  align-items: center;
  justify-content: center;
  flex: 1 1 auto;
  width: 100%;
  margin-top: 0;
}
.kpi-icon {
  font-size: clamp(48px, calc(16px + 4.17vw), 96px);
  line-height: 1;
  display: block;
}
.kpi-batt-svg {
  height: clamp(48px, calc(19px + 3.07vw), 78px);
  width: clamp(29px, calc(11.5px + 1.85vw), 47px);
  display: block;
  overflow: visible;
}
.kpi-val {
  position: relative;
  display: inline-flex;
  align-items: baseline;
  justify-content: center;
  font-size: clamp(25px, calc(16px + 1.15vw), 38px);
  font-weight: 600;
  line-height: 1.1;
  margin-top: 2px;
  white-space: nowrap;
}
.kpi-unit {
  position: absolute;
  left: 100%;
  bottom: 1px;
  margin-left: 3px;
  font-size: clamp(14px, 1.0vw, 20px);
  font-weight: 400;
  color: rgba(0, 0, 0, 0.55);
  white-space: nowrap;
}

