var btn = $event.target.closest('#stnTriggerBtn');
if (!btn) { return; }

var existingMenu = document.getElementById('tbStationDropdownMenu');
if (existingMenu) {
  existingMenu.remove();
  return;
}

var rawStns = btn.getAttribute('data-stations');
var stations = [];
try {
  stations = JSON.parse(decodeURIComponent(rawStns || '[]'));
} catch (e) {
  stations = [];
}

var currentId = btn.getAttribute('data-current-id');
var rect = btn.getBoundingClientRect();
var ctx = widgetContext;

var menu = document.createElement('div');
menu.id = 'tbStationDropdownMenu';
menu.style.position = 'fixed';
menu.style.top = (rect.bottom + 4) + 'px';
menu.style.left = rect.left + 'px';
menu.style.width = '260px';
menu.style.maxHeight = '320px';
menu.style.background = '#FFFFFF';
menu.style.border = '1px solid #C9D2DE';
menu.style.borderRadius = '8px';
menu.style.boxShadow = '0 6px 20px rgba(0,0,0,0.15)';
menu.style.zIndex = '999999';
menu.style.fontFamily = 'Roboto,sans-serif';
menu.style.display = 'flex';
menu.style.flexDirection = 'column';
menu.style.overflow = 'hidden';

// Adjust left if overflowing screen right edge
if (rect.left + 260 > window.innerWidth - 10) {
  menu.style.left = (window.innerWidth - 270) + 'px';
}

var searchWrap = document.createElement('div');
searchWrap.style.padding = '8px 10px';
searchWrap.style.borderBottom = '1px solid #ECEFF3';
searchWrap.style.background = '#FAFBFD';

var searchInput = document.createElement('input');
searchInput.id = 'tbStnSearchInput';
searchInput.type = 'text';
searchInput.placeholder = '🔍 Search station or location...';
searchInput.style.width = '100%';
searchInput.style.boxSizing = 'border-box';
searchInput.style.border = '1px solid #C9D2DE';
searchInput.style.borderRadius = '6px';
searchInput.style.padding = '6px 9px';
searchInput.style.fontSize = '12px';
searchInput.style.outline = 'none';
searchInput.style.fontFamily = 'Roboto,sans-serif';
searchInput.style.background = '#FFFFFF';
searchWrap.appendChild(searchInput);
menu.appendChild(searchWrap);

var listWrap = document.createElement('div');
listWrap.id = 'tbStnListWrap';
listWrap.style.maxHeight = '240px';
listWrap.style.overflowY = 'auto';
listWrap.style.padding = '4px 0';
menu.appendChild(listWrap);

function renderList(query) {
  listWrap.innerHTML = '';
  var q = (query || '').toLowerCase().trim();
  var filtered = stations.filter(function(s) {
    if (!q) return true;
    return s.name.toLowerCase().includes(q) || (s.desc && s.desc.toLowerCase().includes(q));
  });

  if (filtered.length === 0) {
    var empty = document.createElement('div');
    empty.style.padding = '12px 10px';
    empty.style.fontSize = '12px';
    empty.style.color = '#888';
    empty.style.textAlign = 'center';
    empty.innerText = 'No matching stations';
    listWrap.appendChild(empty);
    return;
  }

  filtered.forEach(function(s) {
    var isSel = (s.id === currentId);
    var item = document.createElement('div');
    item.className = 'tb-stn-opt';
    item.style.padding = '8px 12px';
    item.style.cursor = 'pointer';
    item.style.borderBottom = '1px solid #F5F7FA';
    item.style.display = 'flex';
    item.style.flexDirection = 'column';
    item.style.gap = '2px';
    item.style.background = isSel ? '#F0F4F8' : '#FFFFFF';
    item.style.transition = 'background .1s';

    item.onmouseenter = function() { item.style.background = isSel ? '#E2EAF2' : '#F7FAFC'; };
    item.onmouseleave = function() { item.style.background = isSel ? '#F0F4F8' : '#FFFFFF'; };

    var titleRow = document.createElement('div');
    titleRow.style.display = 'flex';
    titleRow.style.justifyContent = 'space-between';
    titleRow.style.alignItems = 'center';

    var nameSpan = document.createElement('span');
    nameSpan.style.fontWeight = isSel ? '700' : '600';
    nameSpan.style.fontSize = '13px';
    nameSpan.style.color = isSel ? '#1976D2' : '#29313C';
    nameSpan.innerText = s.name;
    titleRow.appendChild(nameSpan);

    if (isSel) {
      var check = document.createElement('span');
      check.style.color = '#1976D2';
      check.style.fontWeight = '700';
      check.style.fontSize = '13px';
      check.innerHTML = '&#10003;';
      titleRow.appendChild(check);
    }
    item.appendChild(titleRow);

    if (s.desc) {
      var descSpan = document.createElement('span');
      descSpan.style.fontSize = '11px';
      descSpan.style.color = '#64748B';
      descSpan.innerText = s.desc;
      item.appendChild(descSpan);
    }

    item.onclick = function(e) {
      e.stopPropagation();
      menu.remove();
      cleanUpListeners();
      if (!isSel) {
        var curState = ctx.stateController.getStateId();
        ctx.stateController.updateState(curState, {
          entityId: { id: s.id, entityType: s.type },
          entityName: s.rawName
        }, false);
      }
    };

    listWrap.appendChild(item);
  });
}

renderList('');
document.body.appendChild(menu);
setTimeout(function() { searchInput.focus(); }, 50);

searchInput.oninput = function() {
  renderList(searchInput.value);
};

function onDocClick(e) {
  if (!menu.contains(e.target) && e.target !== btn && !btn.contains(e.target)) {
    menu.remove();
    cleanUpListeners();
  }
}

function onDocKey(e) {
  if (e.key === 'Escape') {
    menu.remove();
    cleanUpListeners();
  }
}

function cleanUpListeners() {
  document.removeEventListener('click', onDocClick, true);
  document.removeEventListener('keydown', onDocKey, true);
}

document.addEventListener('click', onDocClick, true);
document.addEventListener('keydown', onDocKey, true);

