// Global auto-close notification infrastructure
if (typeof window !== 'undefined') {
  if (!window.tbAutoCloseObserverAttached) {
    window.tbAutoCloseObserverAttached = true;
    var tbToastObserver = new MutationObserver(function() {
      var toasts = document.querySelectorAll('tb-snack-bar-component');
      for (var i = 0; i < toasts.length; i++) {
        var t = toasts[i];
        if (!t.getAttribute('data-autoclose-armed')) {
          t.setAttribute('data-autoclose-armed', '1');
          setTimeout(function() {
            var btn = t.querySelector('button');
            if (btn) { btn.click(); }
            else if (t.parentNode) { t.parentNode.removeChild(t); }
          }, 5000);
        }
      }
    });
    tbToastObserver.observe(document.body, { childList: true, subtree: true });
  }

  var curCtx = (typeof widgetContext !== 'undefined' ? widgetContext : (this && this.ctx ? this.ctx : null));
  if (curCtx && curCtx.constructor && curCtx.constructor.prototype && !curCtx.constructor.prototype.__autoclose_patched) {
    curCtx.constructor.prototype.__autoclose_patched = true;
    var _origShowErrorToast = curCtx.constructor.prototype.showErrorToast;
    curCtx.constructor.prototype.showErrorToast = function(msg, vPos, hPos, target, forceDismiss) {
      if (this.showToast) {
        this.showToast('error', msg, 5000, vPos || 'top', hPos || 'right', target || 'dashboardRoot', forceDismiss);
      } else if (_origShowErrorToast) {
        _origShowErrorToast.call(this, msg, vPos, hPos, target, forceDismiss);
      }
    };
  }
}


var rawName = '';
if (data && data.length && data[0] && ((data[0].entityName || '').replace(/-view.*$/, ''))) rawName = ((data[0].entityName || '').replace(/-view.*$/, ''));
var cleanName = String(rawName).replace(/-view(-researchers)?$/, '');

var d = (data && data[0]) ? data[0] : {};
var raw = d['AqiVal'];
var aqi = (raw === undefined || raw === null || raw === '') ? null : parseFloat(raw);
if (aqi !== null && isNaN(aqi)) aqi = null;

var pill = '';
if (aqi !== null) {
  var bands = [
    [50,  '#009966', '#ffffff', 'Good'],
    [100, '#FFDE33', '#3d3d00', 'Moderate'],
    [150, '#FF9933', '#ffffff', 'Unhealthy (sensitive)'],
    [200, '#CC0033', '#ffffff', 'Unhealthy'],
    [300, '#660099', '#ffffff', 'Very unhealthy'],
    [1e9, '#7E0023', '#ffffff', 'Hazardous']
  ];
  var b = bands[bands.length - 1];
  for (var i = 0; i < bands.length; i++) { if (aqi <= bands[i][0]) { b = bands[i]; break; } }
  pill = '<span class="nh-pill" style="background:' + b[1] + ';color:' + b[2] + ';">' +
           '<span class="nh-pill-n">' + Math.round(aqi) + '</span> AQI &middot; ' + b[3] +
         '</span>';
}

var hdrTs = d['HdrTs|ts'];
var lastUpdated = (hdrTs && typeof moment !== 'undefined') ? '<div class="node-hdr-updated">Last updated ' + moment(Number(hdrTs)).fromNow() + '</div>' : '';

var stations = [];
var seen = {};
if (data && data.length) {
  for (var j = 0; j < data.length; j++) {
    var item = data[j];
    if (item && item.entityId && !seen[item.entityId]) {
      seen[item.entityId] = true;
      var eName = item.entityName || '';
      var cName = String(eName).replace(/-view(-researchers)?$/, '');
      var isRet = item['stn_retired'] === true || item['stn_retired'] === 'true';
      var desc = item['stn_desc'] || '';
      if (!isRet && cName) {
        stations.push({
          id: item.entityId,
          type: item.entityType || 'DEVICE',
          name: cName,
          rawName: eName,
          desc: desc
        });
      }
    }
  }
}
stations.sort(function(a, b) { return a.name.localeCompare(b.name); });
var stnsJson = encodeURIComponent(JSON.stringify(stations));

return '<div class="node-hdr">' +
         '<div class="stn-select-wrap">' +
           '<button id="stnTriggerBtn" class="stn-trigger-btn" type="button" title="Click to switch station" data-current-id="' + (data[0] ? data[0].entityId : '') + '" data-stations="' + stnsJson + '">' +
             '<span class="stn-trigger-text">' + (cleanName || 'Select station') + '</span>' +
             '<span class="stn-trigger-arrow">&#9662;</span>' +
           '</button>' +
         '</div>' +
         pill +
         lastUpdated +
       '</div>';

