    unitStr = '%';
    battColor = soc < 25 ? 'var(--tb-danger, #B3261E)' : (soc < 50 ? 'var(--tb-warn, #F9A825)' : 'var(--tb-ok, #1E6C33)');
    valColor = battColor;
  }
} else if (isFault) {
  battColor = 'var(--tb-danger, #B3261E)';
  valColor = 'var(--tb-danger, #B3261E)';
} else if (isMasked) {
  battColor = '#9E9E9E';
  valColor = '#9E9E9E';
}

var cap = '<rect x="7" y="1" width="10" height="3" rx="1.5" fill="currentColor"/>';
var body = '<rect x="2" y="4" width="20" height="35" rx="3.5" fill="none" stroke="currentColor" stroke-width="2.5"/>';
var inner = '';

if (isOk && soc !== null) {
  var p = Math.max(0, Math.min(100, soc));
  var fillH = Math.round(30 * (p / 100));
  if (p > 0 && fillH < 2) fillH = 2;
  if (fillH > 0) {
    var fillY = (36.5 - fillH).toFixed(1);
    inner = '<rect x="4.5" y="' + fillY + '" width="15" height="' + fillH + '" rx="2" fill="currentColor"/>';
  }
} else if (isFault) {
  inner = '<text x="12" y="27" font-size="20" font-weight="bold" text-anchor="middle" fill="currentColor" font-family="sans-serif">!</text>';
} else {
  inner = '<text x="12" y="27" font-size="20" font-weight="bold" text-anchor="middle" fill="currentColor" font-family="sans-serif">?</text>';
}

var svgHtml = '<svg class="kpi-batt-svg" viewBox="0 0 24 40" style="color:' + battColor + ';">' + cap + body + inner + '</svg>';

return '<div class="kpi-card">' +
  '<div class="kpi-top">' +
    '<span class="kpi-title">Battery</span>' +
    '<span class="kpi-pill ' + pillCls + '">' + pillText + '</span>' +
  '</div>' +
  '<div class="kpi-body">' +
    svgHtml +
    '<div class="kpi-val" style="color:' + valColor + ';">' +
      valStr + (unitStr ? '<span class="kpi-unit">' + unitStr + '</span>' : '') +
    '</div>' +
  '</div>' +
  (function() {
    var _n = (valStr !== '--' && !isNaN(parseFloat(valStr))) ? parseFloat(valStr) : null;
    var _s = valStr + (unitStr ? ' ' + unitStr : '');
    var _c = (typeof iconColor !== 'undefined') ? iconColor : ((typeof battColor !== 'undefined') ? battColor : ((typeof valColor !== 'undefined') ? valColor : ''));
    var _ev = 'window.tbKpiInfoValue={metric:\'battery\',val:' + _n + ',str:\'' + _s + '\',color:\'' + _c + '\'};' ;
    return '<button id="info" class="kpi-info-btn" aria-label="Information" onmousedown="' + _ev + '" onclick="' + _ev + '">' +
      '<i class="material-icons">info_outline</i>' +
    '</button>';
  })() +
'</div>';
}).call(this);
if (__tbC) { __tbC.__tbKpiLast = __tbOut; }
return __tbOut;

