// Global auto-close notification infrastructure
if (typeof window !== 'undefined') {
  if (!window.tbAutoCloseObserverAttached) {
    window.tbAutoCloseObserverAttached = true;
    var tbToastObserver = new MutationObserver(function() {
      var toasts = document.querySelectorAll('tb-snack-bar-component');
      for (var i = 0; i < toasts.length; i++) {
        var t = toasts[i];
        if (!t.getAttribute('data-autoclose-armed')) {
          t.setAttribute('data-autoclose-armed', '1');
          setTimeout(function() {
            var btn = t.querySelector('button');
            if (btn) { btn.click(); }
            else if (t.parentNode) { t.parentNode.removeChild(t); }
          }, 5000);
        }
      }
    });
    tbToastObserver.observe(document.body, { childList: true, subtree: true });
  }

  var curCtx = (typeof widgetContext !== 'undefined' ? widgetContext : (this && this.ctx ? this.ctx : null));
  if (curCtx && curCtx.constructor && curCtx.constructor.prototype && !curCtx.constructor.prototype.__autoclose_patched) {
    curCtx.constructor.prototype.__autoclose_patched = true;
    var _origShowErrorToast = curCtx.constructor.prototype.showErrorToast;
    curCtx.constructor.prototype.showErrorToast = function(msg, vPos, hPos, target, forceDismiss) {
      if (this.showToast) {
        this.showToast('error', msg, 5000, vPos || 'top', hPos || 'right', target || 'dashboardRoot', forceDismiss);
      } else if (_origShowErrorToast) {
        _origShowErrorToast.call(this, msg, vPos, hPos, target, forceDismiss);
      }
    };
  }
}

var d = (data && data[0]) ? data[0] : {};

function num(v) {
  if (v === undefined || v === null || v === '') return null;
  var n = parseFloat(v);
  return isNaN(n) ? null : n;
}

function ts(label) {
  var t = d[label + '|ts'];
  if (t === undefined || t === null || t === '') return null;
  t = Number(t);
  return isNaN(t) ? null : t;
}

function ageStr(t) {
  if (t === null) return null;
  return moment(t).fromNow();
}
function fullStr(t) {
  return t === null ? '' : moment(t).format('D MMM YYYY HH:mm');
}

var sf   = num(d['SF']);
var bw   = num(d['BW']);
var toa  = num(d['ToA']);
var tx   = num(d['TxInt']);
var snr  = num(d['SNR']);
var fcnt = num(d['Fcnt']);
var modeName = d['Mode'];
var wmin = num(d['WinMin']);
var wmax = num(d['WinMax']);
var rcvd = num(d['Rcvd']);
var exp  = num(d['Expected']);
var miss = num(d['Missing']);
var txp  = num(d['TxPwr']);
var chan = num(d['Chan']);

// Last uplink timestamp (freshest proof of life)
var upTs  = ts('Fcnt');
var upStr = ageStr(upTs) || 'N/A';
var upTip = fullStr(upTs);
var upSub = upTs ? ('Received at ' + moment(upTs).format('HH:mm:ss') + ' · refreshed every uplink') : 'no uplink received yet';

// Modulation
var modulation = 'N/A', modSub = '';
if (sf !== null) {
  modulation = 'SF' + Math.round(sf);
  if (bw !== null) modulation += ' · ' + Math.round(bw / 1000) + ' kHz';
  var modAge = ageStr(ts('SF')) || upStr;
  modSub = 'LoRa spreading factor & bandwidth' + (modAge && modAge !== 'N/A' ? ' · updated ' + modAge : '');
}

// Time on air
var toaStr = 'N/A', toaSub = '';
if (toa !== null) {
  toaStr = toa.toFixed(1) + ' ms';
  var toaAge = ageStr(ts('ToA')) || upStr;
  toaSub = 'Calculated packet airtime' + (toaAge && toaAge !== 'N/A' ? ' · updated ' + toaAge : '');
}

// Link margin
var SNR_FLOOR = { 7: -7.5, 8: -10, 9: -12.5, 10: -15, 11: -17.5, 12: -20 };
var marginStr = 'N/A', marginSub = '';
if (snr !== null && sf !== null) {
  var floor = SNR_FLOOR[Math.round(sf)];
  if (floor !== undefined) {
    var margin = snr - floor;
    marginStr = (margin >= 0 ? '+' : '') + margin.toFixed(1) + ' dB';
    var snrAge = ageStr(ts('SNR')) || upStr;
    marginSub = 'SNR ' + snr.toFixed(1) + ' vs SF' + Math.round(sf) + ' floor ' + floor + ' dB' +
                (snrAge && snrAge !== 'N/A' ? ' · updated ' + snrAge : '');
  }
}

// TX interval
var txStr = 'N/A', txSub = 'no status ping received yet', txTip = '';
if (tx !== null) {
  txStr = (tx >= 60) ? (Math.round(tx / 60 * 10) / 10) + ' min (' + tx + ' s)' : tx + ' s';
  var txAge = ageStr(ts('TxInt'));
  txSub = 'Configured uplink cadence · ' + (txAge ? 'as of ' + txAge + ' (ping only)' : 'refreshed by status ping only');
  txTip = fullStr(ts('TxInt'));
}

// Operating mode
var MODE_LOW_MID_HIGH = { 'NORMAL': 'Mid', 'NORMAL_NO_GAS': 'Low', 'ALWAYS_ON': 'High' };
var modeStr = 'N/A', modeSub = 'no status ping received yet', modeTip = '';
if (modeName) {
  modeStr = MODE_LOW_MID_HIGH[modeName] || modeName;
  var modeAge = ageStr(ts('Mode'));
  modeSub = 'Active operating profile · ' + (modeAge ? 'as of ' + modeAge + ' · may revert on reset' : 'may revert on reset');
  modeTip = fullStr(ts('Mode'));
}

// Frame counter
var fcntStr = 'N/A', fcntSub = '';
if (fcnt !== null) {
  fcntStr = String(fcnt);
  var fcntAge = ageStr(ts('Fcnt'));
  fcntSub = 'LoRaWAN uplink counter (f_cnt)' + (fcntAge && fcntAge !== 'N/A' ? ' · updated ' + fcntAge : '');
}

// TX power
var txpStr = 'N/A', txpSub = 'no status ping received yet', txpTip = '';
if (txp !== null) {
  txpStr = txp + ' dBm';
  var txpAge = ageStr(ts('TxPwr'));
  txpSub = 'RF transmit output power · ' + (txpAge ? 'as of ' + txpAge + ' (ping only)' : 'refreshed by status ping only');
  txpTip = fullStr(ts('TxPwr'));
}

// Channel
var chanStr = 'N/A', chanSub = 'no status ping received yet', chanTip = '';
if (chan !== null) {
  chanStr = String(chan);
  var chanAge = ageStr(ts('Chan'));
  chanSub = 'Uplink radio frequency channel · ' + (chanAge ? 'as of ' + chanAge + ' (ping only)' : 'refreshed by status ping only');
  chanTip = fullStr(ts('Chan'));
}

// PDR window
var partialRaw = d['Partial'];
var partial = (partialRaw === true || partialRaw === 'true');

var winStr = 'N/A', winSub = '';
if (partial) {
  winStr = '⏳ Warming up';
  winSub = (fcnt !== null ? 'frame ' + fcnt + ' since reset · ' : '') +
           'PDR paused, tile shows last known value';
} else if (wmin !== null && wmax !== null) {
  winStr = wmin + ' – ' + wmax;
  var pdrAge = ageStr(ts('WinMax')) || upStr;
  var missCount = (miss !== null && miss > 0) ? miss : 0;
  var rcvdCount = rcvd !== null ? rcvd : 0;
  var expCount = exp !== null ? exp : (rcvdCount + missCount);
  winSub = 'Sliding delivery window · ' + rcvdCount + ' of ' + expCount + ' received (' + missCount + ' missing)' +
           (pdrAge && pdrAge !== 'N/A' ? ' · updated ' + pdrAge : '');
}

var rows = [
  ['Modulation',    modulation, modSub,    ''],
  ['Time on air',   toaStr,     toaSub,    ''],
  ['Link margin',   marginStr,  marginSub, ''],
  ['TX interval',   txStr,      txSub,     txTip],
  ['Mode',          modeStr,    modeSub,   modeTip],
  ['Last uplink',   upStr,      upSub,     upTip],
  ['Frame counter', fcntStr,    fcntSub,   ''],
  ['TX power',      txpStr,     txpSub,    txpTip],
  ['Channel',       chanStr,    chanSub,   chanTip],
  [partial ? 'PDR status' : 'PDR window', winStr, winSub, '']
];

var html = rows.map(function (r) {
  var na  = (r[1] === 'N/A') ? ' na' : '';
  var tip = r[3] ? ' matTooltip="' + r[3] + '" matTooltipPosition="left"' : '';
  var sub = r[2] ? '<div class="ld-tsub">' + r[2] + '</div>' : '';
  return '<div class="ld-tile">' +
           '<div class="ld-tk">' + r[0] + '</div>' +
           '<div class="ld-col">' +
             '<div class="ld-tv' + na + '"' + tip + '>' + r[1] + '</div>' +
             sub +
           '</div>' +
         '</div>';
}).join('');

return '<div class="link-card">' +
         '<div class="link-title">Link details</div>' +
         '<div class="ld-tiles">' + html + '</div>' +
       '</div>';

