settings.markdownTextFunction:
/* Phone navigation bar shared by every application (LAURA, AquaTrace). Styled by shared_widgets/nav_tabs.css.
   window.tbNavBar(ctx, root, labels) upgrades the .hdr-tabs inside `root`, once:
   - each tab gets a Material icon (data-icon) chosen by its state id,
   - with more than 4 tabs the ones beyond the fourth are copied into the drawer (.nav-item) and hidden in the bar (.nav-over),
   - a last "More" slot opens the drawer (button, scrim tap, swipe right from the left edge, swipe left to close),
   - the drawer ends with the account section: user, Profile (password change), About, Log out.
   Full bleed pages (?hideToolbar=true) have no ThingsBoard user menu, hence the account section. Public (anonymous) pages
   get About only. Above 960 px the CSS hides everything this adds, so the desktop tab row is unchanged.
   labels: {more, account, profile, about, about_text, logout, pw_current, pw_new, pw_confirm, pw_save, pw_saved, pw_mismatch, pw_failed}. */
(function() {
  var ICONS = { default: 'dashboard', route: 'route', children: 'child_care', privacy: 'lock', wearables: 'watch', gateways: 'router',
    families: 'family_restroom', school_admin: 'school', settings: 'settings', operations: 'tune', dma_config: 'tune', users: 'group',
    alarm_queue: 'notifications', survey_orders: 'assignment', commission: 'sensors', metrics: 'insights',
    AQI: 'map', node_sensor: 'thermostat', node_network: 'network_check', node_downlink: 'tune', fleet_control: 'devices' };
  var BAR_TABS = 4;
  var TOKEN_KEYS = ['jwt_token', 'jwt_token_expiration', 'refresh_token', 'refresh_token_expiration'];

  function esc(s) { return String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }

  // same storage ThingsBoard's own AuthService writes (jwt_token, jwt_token_expiration, refresh_token, refresh_token_expiration)
  function storeToken(name, jwt) {
    try {
      var p = JSON.parse(atob(jwt.split('.')[1].replace(/-/g, '+').replace(/_/g, '/')));
      localStorage.setItem(name, jwt);
      localStorage.setItem(name + '_expiration', String(p.exp * 1000));
    } catch (e) {}
  }

  function logout(ctx) {
    var done = function() {
      TOKEN_KEYS.forEach(function(k) { try { localStorage.removeItem(k); } catch (e) {} });
      window.location.href = '/login';
    };
    try { ctx.http.post('/api/auth/logout', {}).subscribe(done, done); } catch (e) { done(); }
  }

  function changePassword(ctx, cur, next, cb) {
    try {
      ctx.http.post('/api/auth/changePassword', { currentPassword: cur, newPassword: next }).subscribe(function(r) {
        if (r && r.token) storeToken('jwt_token', r.token);            // the server invalidates the old token pair
        if (r && r.refreshToken) storeToken('refresh_token', r.refreshToken);
        cb(true);
      }, function(e) { cb(false, e && e.error && e.error.message); });
    } catch (e) { cb(false); }
  }

  function setOpen(bar, v) { bar.classList.toggle('nav-open', v); }

  function markMore(bar) { var more = bar.querySelector('.nav-more'); if (more) more.classList.toggle('nav-on', !!bar.querySelector('.nav-item.flt-pill-active')); }

  window.tbNavBar = function(ctx, root, L) {
    var bar = root && root.querySelector('.hdr-tabs');
    if (!bar || bar.getAttribute('data-nav')) return;
    bar.setAttribute('data-nav', '1');
    L = L || {};
    var user = ctx && ctx.currentUser, pub = !user || user.isPublic;
    var tabs = [].slice.call(bar.querySelectorAll('.hdr-tab'));
    tabs.forEach(function(t) { t.setAttribute('data-icon', ICONS[t.getAttribute('data-state')] || 'circle'); });

    var scrim = document.createElement('div'); scrim.className = 'nav-scrim';
    var panel = document.createElement('div'); panel.className = 'nav-panel';
    var h = '<div class="nav-head">' + esc(L.more) + '</div>';
    tabs.slice(BAR_TABS).forEach(function(t) {
      t.classList.add('nav-over');
      h += '<button type="button" class="nav-item' + (t.classList.contains('flt-pill-active') ? ' flt-pill-active' : '') + '" data-state="' + esc(t.getAttribute('data-state')) +
        '" data-icon="' + esc(t.getAttribute('data-icon')) + '">' + t.innerHTML + '</button>';
    });
    if (tabs.length > BAR_TABS) h += '<div class="nav-sep"></div>';
    if (!pub) {
      h += '<div class="nav-user">' + esc(user.sub || user.email || '') + '</div>' +
        '<button type="button" class="nav-item" data-icon="manage_accounts" data-fold="profile">' + esc(L.profile) + '</button>' +
        '<div class="nav-fold" data-fold-box="profile"><div class="nav-msg"></div>' +
        '<input type="password" class="nav-pw0" autocomplete="current-password" placeholder="' + esc(L.pw_current) + '">' +
        '<input type="password" class="nav-pw1" autocomplete="new-password" placeholder="' + esc(L.pw_new) + '">' +
        '<input type="password" class="nav-pw2" autocomplete="new-password" placeholder="' + esc(L.pw_confirm) + '">' +
        '<button type="button" class="nav-save">' + esc(L.pw_save) + '</button></div>';
    }
    h += '<button type="button" class="nav-item" data-icon="info" data-fold="about">' + esc(L.about) + '</button>' +
      '<div class="nav-fold" data-fold-box="about">' + esc(L.about_text) + '</div>';
    if (!pub) h += '<button type="button" class="nav-item nav-danger" data-icon="logout" data-logout="1">' + esc(L.logout) + '</button>';
    panel.innerHTML = h;

    var more = document.createElement('button'); more.type = 'button'; more.className = 'nav-more'; more.textContent = L.more || 'More';
    bar.appendChild(more); bar.appendChild(scrim); bar.appendChild(panel);
    markMore(bar);

    more.addEventListener('click', function() { setOpen(bar, !bar.classList.contains('nav-open')); });
    // a tab and its drawer copy are one page: after the header's own click handler moved the highlight, give both the same state, then light More
    bar.addEventListener('click', function() {
      setTimeout(function() {
        var on = {};
        [].slice.call(bar.querySelectorAll('[data-state].flt-pill-active')).forEach(function(e) { on[e.getAttribute('data-state')] = 1; });
        [].slice.call(bar.querySelectorAll('[data-state]')).forEach(function(e) { e.classList.toggle('flt-pill-active', !!on[e.getAttribute('data-state')]); });
        markMore(bar);
      }, 80);
    });
    scrim.addEventListener('click', function() { setOpen(bar, false); });
    panel.addEventListener('click', function(e) {
      var b = e.target.closest('button'); if (!b) return;
      if (b.getAttribute('data-state')) { setTimeout(function() { setOpen(bar, false); }, 60); return; }
      if (b.getAttribute('data-logout')) { logout(ctx); return; }
      var f = b.getAttribute('data-fold');
      if (f) {
        var box = panel.querySelector('[data-fold-box="' + f + '"]');
        [].slice.call(panel.querySelectorAll('.nav-fold')).forEach(function(x) { if (x !== box) x.classList.remove('nav-shown'); });
        if (box) box.classList.toggle('nav-shown');
        return;
      }
      if (b.classList.contains('nav-save')) {
        var box2 = b.closest('.nav-fold'), msg = box2.querySelector('.nav-msg');
        var c = box2.querySelector('.nav-pw0').value, n1 = box2.querySelector('.nav-pw1').value, n2 = box2.querySelector('.nav-pw2').value;
        msg.classList.remove('nav-ok');
        if (!c || !n1) { msg.textContent = L.pw_failed; return; }
        if (n1 !== n2) { msg.textContent = L.pw_mismatch; return; }
        b.disabled = true;
        changePassword(ctx, c, n1, function(ok, why) {
          b.disabled = false;
          msg.textContent = ok ? L.pw_saved : (why || L.pw_failed);
          msg.classList.toggle('nav-ok', !!ok);
          if (ok) ['.nav-pw0', '.nav-pw1', '.nav-pw2'].forEach(function(s) { box2.querySelector(s).value = ''; });
        });
      }
    });

    // one document level swipe handler for the page, always acting on the bar that is on screen
    if (!window.__tbNavSwipe) {
      window.__tbNavSwipe = true;
      var sx = null, sy = 0;
      document.addEventListener('touchstart', function(e) { var t = e.touches[0]; sx = t.clientX; sy = t.clientY; }, { passive: true });
      document.addEventListener('touchend', function(e) {
        if (sx === null) return;
        var cur = document.querySelector('.hdr-tabs[data-nav]'), t = e.changedTouches[0], dx = t.clientX - sx, dy = Math.abs(t.clientY - sy);
        if (cur && window.matchMedia('(max-width: 959px)').matches) {
          var open = cur.classList.contains('nav-open');
          if (!open && sx < 28 && dx > 60 && dy < 60) setOpen(cur, true);
          else if (open && dx < -60 && dy < 60) setOpen(cur, false);
        }
        sx = null;
      }, { passive: true });
    }
  };
})();

var LB = {"more": "More", "profile": "Profile and password", "about": "About", "about_text": "Air quality monitor: LoRaWAN sensor network in Yaoundé. Dashboards run on ThingsBoard CE 4.3.", "logout": "Log out", "pw_current": "Current password", "pw_new": "New password", "pw_confirm": "Repeat new password", "pw_save": "Change password", "pw_saved": "Password changed.", "pw_mismatch": "The two new passwords differ.", "pw_failed": "Password not changed. Check the current password."};
var SPEC = [["AQI", "Map"], ["node_sensor", "Sensor"], ["node_network", "Network"], ["node_downlink", "Control"], ["fleet_control", "Fleet"]];
var tries = 0;
// the native buttons belong to the current page and are replaced on every state change: look them up when needed
function findNative(label) {
  var hit = null;
  [].slice.call(document.querySelectorAll('tb-widget-button button')).forEach(function(b) {
    if ((b.textContent || '').replace(/arrow_back/g, '').trim() === label) hit = b;
  });
  return hit;
}
(function build() {
  var root = document.getElementById('aqiNavRoot'), host = document.getElementById('aqiNav');
  // this function runs before its own markup and the native buttons are in the page: wait for both (at most 6 s)
  if (!root || !host || !document.querySelector('tb-widget-button button')) { if (tries++ < 30) setTimeout(build, 200); return; }
  if (host.getAttribute('data-built')) return;
  var cur = ctx.stateController.getStateId(), h = '';
  SPEC.forEach(function(s) {
    if (findNative(s[1])) h += '<button type="button" class="hdr-tab' + (s[0] === cur ? ' flt-pill-active' : '') + '" data-state="' + s[0] + '">' + s[1] + '</button>';
  });
  host.setAttribute('data-built', '1');
  host.innerHTML = h;
  root.addEventListener('click', function(e) {
    var t = e.target.closest('[data-state]'); if (!t) return;
    var st = t.getAttribute('data-state'), lab = '', nb;
    SPEC.forEach(function(s) { if (s[0] === st) lab = s[1]; });
    // the header widget is shared by the pages and TB does not redraw it on a state change: move the highlight here
    [].slice.call(root.querySelectorAll('[data-state]')).forEach(function(x) { x.classList.toggle('flt-pill-active', x.getAttribute('data-state') === st); });
    if ((nb = findNative(lab))) nb.click();
  });
  if (window.tbNavBar) window.tbNavBar(ctx, root, LB);
})();
return '<div id="aqiNavRoot"><div class="hdr-tabs" id="aqiNav"></div></div>';

settings.dashboardCss:
/* ==== Shared design tokens (2026-09-17) ====
   Single source of truth for colors/fonts reused across tabs. Each per-widget
   markdownCss reference below carries its original literal as a var() fallback,
   so this can never regress current rendering even if the cascade path changes. */
* {
  --tb-navy: #305680;
  --tb-navy-hover: #254466;
  --tb-danger: #B3261E;
  --tb-ok: #1E6C33;
  --tb-warn: #F9A825;
  --tb-aqi-sensitive: #D35400;
  --tb-aqi-very-unhealthy: #660099;
  --tb-aqi-hazardous: #7E0023;
  --tb-blue: #5469FF;
  --tb-blue-dark: #1565C0;
  --tb-ink-secondary: rgba(41, 49, 60, 0.72);
  --tb-ink-muted: rgba(41, 49, 60, 0.45);

  --tb-slate: #64748B;
  --tb-slate-light: #94A3B8;
  --tb-ok-bg: #E3F5EA;
  --tb-danger-bg: #FEE2E2;
  --tb-danger-text: #991B1B;
  --tb-warn-bg: #FEF3C7;
  --tb-warn-text: #92400E;
  --tb-card-radius: 15px;
  --tb-badge-radius: 9999px;
  --tb-mono: ui-monospace,"SF Mono",Menlo,Monaco,Consolas,monospace;
  --tb-btn-w: 104px;
  --tb-btn-h: 34px;
  --tb-btn-font: 12.5px;
  --tb-btn-radius: 8px;
  --tb-font: Roboto, sans-serif;
  --tb-border: #C9D2DE;
  --tb-ink: #29313C;
  --tb-danger-text-soft: #8C1D18;
  --tb-danger-card-bg: #FFF8F7;
  --tb-danger-card-border: #F3D3CE;
  --tb-danger-btn-border: #E8B4AE;
  --tb-danger-hover-bg: #FCEEEC;
  --tb-warn-text-soft: #8A5A00;
  --tb-warn-btn-border: #E6D2A8;
  --tb-warn-hover-bg: #FDF6E7;
  --tb-warn-hover-border: #B3800B;
  --tb-scrollbar-radius: 3px;
  --tb-tag-radius: 4px;
}
/* ==== end shared design tokens ==== */

.tb-dashboard-page .mat-drawer-container, .tb-dashboard-page .tb-progress-cover, .tb-markdown-view .tb-progress-cover, .tb-markdown-view .mat-drawer-container {
    background-color: #fff;
}



/* Aqi Components Popup Styles */

.aqi-component-desc-popup {
    width: 100%;
    height: 100%;
    padding: 20px 24px 28px 24px;
}

.aqi-component-desc-popup .header,
.aqi-component-desc-popup .component-name-header {
    font-weight: 600;
    font-size: 22px;
    line-height: 28px;
    letter-spacing: 0.25px;
    color: #29313C;
}

.aqi-component-desc-popup .component-name-header {
    margin-bottom: 4px;
}

.aqi-component-desc-popup .header {
    margin-bottom: 16px;
}

.aqi-component-desc-popup .entity-name-header {
    margin-bottom: 24px;
    font-weight: 500;
    font-size: 18px;
    line-height: 24px;
    letter-spacing: 0.25px;
    color: #9FA6B4;
}

.aqi-component-desc-popup .history-container {
    height: 65%;
    width: 100%;
    margin-bottom: 40px;
}

.aqi-component-desc-popup .history-container .history-tabs .mat-mdc-tab-header {
    border-bottom: none;
}

.aqi-component-desc-popup .history-container .history-tabs .mat-mdc-tab {
    height: 40px;
    min-width: 50px;
    opacity: 1;
}

.aqi-component-desc-popup .history-container .history-tabs .mat-mdc-tab .mdc-tab__text-label {
    font-size: 14px;
    font-weight: 600;
    line-height: 20px;
    color: #9FA6B4;
}

.aqi-component-desc-popup .history-container .history-tabs .mat-mdc-tab.mdc-tab--active .mdc-tab__text-label {
    color: #29313C;
}

.aqi-component-desc-popup .history-container .history-tabs .mat-mdc-tab .mdc-tab-indicator__content--underline {
    border-color: #4B535B;
}

.aqi-component-desc-popup .history-container .history-tabs {
    height: 100%;
}

.aqi-component-desc-popup .history-container .history-tabs .mat-mdc-tab-body-wrapper {
    height: calc(100% - 40px);
}

.aqi-component-desc-popup .component-values-container {
    margin-bottom: 24px;
}

.aqi-component-desc-popup .component-values-container > div:not(:last-child) {
    margin-right: 24px;
}

.aqi-component-desc-popup .component-value-header {
    margin-bottom: 8px;
    font-weight: 500;
    font-size: 14px;
    line-height: 18px;
    letter-spacing: 0.25px;
    color: #9FA6B4;
}

.aqi-component-desc-popup .component-value-row {
    display: flex;
    flex-direction: row;
    font-size: 14px;
}

.aqi-component-desc-popup .component-value {
    margin-right: 4px;
    line-height: 20px;
    font-weight: 600;
    color: #29313C;
}

.aqi-component-desc-popup .component-unit {
    font-weight: 400;
    line-height: 20px;
    letter-spacing: 0.25px;
    color: #29313C;
}

.aqi-component-desc-popup .component-desc-text {
    font-weight: 400;
    font-size: 14px;
    line-height: 20px;
    letter-spacing: 0.25px;
    color: #29313C;
}

/* === aqi popup: portrait / narrow-viewport layout === */
/* No @media here on purpose - see the note in build_aqi_popup_portrait.py.
   The columns wrap on their own instead: equal flex-basis + equal grow gives the
   exact same widths as the template's `flex-1` while both fit on one line, and
   drops them onto separate lines when they no longer do. */
.aqi-component-desc-popup .aqi-component-desc-content {
    flex-wrap: wrap;
}

.aqi-component-desc-popup .aqi-component-desc-container,
.aqi-component-desc-popup .aqi-quality-levels {
    flex: 1 1 340px;
}

/* Floors, not heights: on a wide popup the template's own sizing already
   exceeds both, so desktop is untouched. Once wrapped, `height: 65%` of an
   indefinite parent collapses to auto and the nested <tb-dashboard-state>
   gridsters (autoFillHeight: true) collapse to zero, so each column needs a
   floor to render into. */
.aqi-component-desc-popup .history-container {
    min-height: 300px;
}

/* Ramped, not constant: a flat floor big enough to hold all six bands on a
   phone would also inflate the desktop popup. This one reaches zero before the
   columns stop wrapping. */
.aqi-component-desc-popup .aqi-quality-levels {
    min-height: max(0px, calc(1087px - 65.85vw), calc(1600px - 200vh));
}

/* TB's own `.tb-markdown-view[_ngcontent] > div[_ngcontent]` hard-codes 32px
   side padding and outranks an unqualified `.aqi-component-desc-popup` rule -
   hence the `.tb-markdown-view` prefix, which wins on the two classes TB
   prepends. Worth 32px of usable width on a 390px screen. */
.tb-markdown-view .aqi-component-desc-popup {
    padding-left: clamp(16px, calc(-64px + 12vw), 32px);
    padding-right: clamp(16px, calc(-64px + 12vw), 32px);
}
/* === end aqi popup portrait === */

/* ==== Shared config-tile frame (2026-09-17) ====
   Single source for the grey-framed group tiles used by Control's Send command
   presets and Fleet's Batch command deck groups. Values match the original
   literals exactly, so this is a pure de-dup, not a visual change. */
.cfg-tiles{display:flex;gap:10px;flex-wrap:wrap;}
.cfg-tile{position:relative;flex:1 1 200px;min-width:180px;border:1px solid rgba(0,0,0,.08);border-radius:10px;
  padding:16px 12px 10px;display:flex;flex-direction:column;gap:4px;}
.cfg-tk{position:absolute;top:0;left:10px;transform:translateY(-50%);background:#fff;padding:0 5px;
  font-size:11px;font-weight:600;letter-spacing:.3px;text-transform:uppercase;
  color:rgba(0,0,0,.4);}




/* ==== Shared config-tile pills (2026-09-17) ====
   Single source for 3-pill button rows across Control and Fleet command decks.
   Governed by --tb-btn-w/h/font/radius design tokens. Responsive clamp() allows
   smooth compression on narrow viewports without relying on @media hoisting. */
.cfg-pills{display:flex;gap:8px;justify-content:center;flex-wrap:nowrap;}
.cfg-pills > button,
.cfg-pills .flt-pill-btn,
.cfg-pills .dl-btn,
.cfg-pills .flt-danger-btn{
  flex:1 1 0px;
  max-width:var(--tb-btn-w, 104px);
  width:100%;
  min-width:0;
  height:clamp(28px, 2.5vw, var(--tb-btn-h, 34px));
  box-sizing:border-box;
  text-align:center;
  padding:clamp(4px, 0.4vw, 6px) clamp(2px, 0.3vw, 4px);
  font-family:var(--tb-font, Roboto,sans-serif);
  font-size:clamp(11px, 0.85vw, var(--tb-btn-font, 12.5px));
  line-height:1;
  border-radius:var(--tb-btn-radius, 8px);
  cursor:pointer;
  user-select:none;
}

/* ==== Shared JSON textbox + stat-tile/detail-row density (2026-09-17 follow-up) ==== */
/* JSON payload textarea, shared by Send command and Fleet's Batch command
   deck. Continuous clamp() sizing on purpose: the earlier @media-scoped
   .dl-json/.flt-json-input base rules were silently dropped by the browser
   (confirmed via live CSSOM inspection, not just theorized) -- an unscoped
   rule sidesteps that failure mode entirely, the same way .cfg-pills already
   does for the button rows. */
.tb-json-input{
  display:block !important;
  width:100%;
  box-sizing:border-box;
  font-family:var(--tb-mono);
  font-size:clamp(11px, 0.85vw, 12.5px);
  line-height:1.4;
  border:1px solid var(--tb-border, #C9D2DE);
  border-radius:var(--tb-btn-radius, 8px);
  padding:clamp(4px, 0.4vw, 6px) 30px clamp(4px, 0.4vw, 6px) clamp(6px, 0.5vw, 10px);
  resize:vertical;
  min-height:clamp(28px, 2.5vw, var(--tb-btn-h, 34px));
  height:clamp(28px, 2.5vw, var(--tb-btn-h, 34px));
  color:var(--tb-ink, #29313C);
  background:#FAFBFD;
  outline:none;
}
.tb-json-input:focus{
  border-color:var(--tb-navy, #305680);
  background:#FFFFFF;
  box-shadow:0 0 0 2px rgba(48,86,128,.15);
}

/* Applied config's 4x4 stat-tile grid. `align-content:start` is the actual
   fix: display:grid defaults to stretching auto-sized rows to fill the
   container, which is what made each tile ~105px tall for two lines of text
   regardless of padding/font tweaks. Content-sized rows plus continuous
   clamp() density (not an @media band that goes inert above 1550px/820px). */
.cfg-stat-tiles{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  align-content:start;
  gap:clamp(4px, 0.4vw, 8px) clamp(6px, 0.6vw, 12px);
  flex:1 1 auto;
  min-height:0;
  overflow-y:auto;
}
.cfg-stat-tile{
  display:flex;
  flex-direction:column;
  align-items:flex-start;
  gap:clamp(0.5px, 0.15vw, 2px);
  padding:clamp(3px, 0.4vw, 6px) clamp(4px, 0.5vw, 8px);
  border:1px solid rgba(0,0,0,.08);
  border-radius:8px;
  flex:0 0 auto;
}
.cfg-stat-k{font-size:clamp(9.5px, 0.7vw, 12px);color:rgba(0,0,0,.55);}
.cfg-stat-v{font-size:clamp(11.5px, 0.85vw, 13px);font-weight:600;color:var(--tb-ink, #29313C);
  flex:1 1 auto;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.cfg-stat-ts{font-size:clamp(9px, 0.65vw, 12px);color:rgba(0,0,0,.38);flex:0 0 auto;white-space:nowrap;}
@media (max-width:600px){
  .cfg-stat-tiles{grid-template-columns:repeat(1,1fr);}
}
@media (min-width:601px) and (max-width:900px){
  .cfg-stat-tiles{grid-template-columns:repeat(2,1fr);}
}

/* Status's delivery-lifecycle detail rows. `justify-content:flex-start`
   (was `space-between`) is the fix: 5 rows were being spread across the
   card's full available height, ballooning the GAP between rows rather than
   any row's own box. Link details' 10-row list looked tighter only because
   more rows absorbed the same available height -- same property, different
   row count. Density calibrated to match Link details' .ld-tile directly. */
.dr-list{display:flex;flex-direction:column;justify-content:flex-start;gap:clamp(4px, 0.3vw, 6px);
  flex:1 1 auto;min-height:0;overflow-y:auto;}
.dr-row{display:flex;align-items:baseline;gap:clamp(6px, 0.6vw, 10px);
  padding:clamp(6px, 0.4vw, 8px) clamp(4px, 0.25vw, 6px);
  border-bottom:1px solid rgba(0,0,0,.06);flex:0 0 auto;}
.dr-row:last-child{border-bottom:none;}
.dr-row:nth-child(even){background:#F8FAFC;}
.dr-k{font-size:clamp(12px, 0.7vw, 13px);color:rgba(0,0,0,.55);flex:0 0 clamp(100px, 6vw, 112px);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.dr-v{font-size:clamp(13px, 0.85vw, 14px);font-weight:600;color:var(--tb-ink, #29313C);line-height:1.2;
  flex:1 1 auto;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.dr-ts{font-size:clamp(11px, 0.65vw, 12px);color:rgba(0,0,0,.38);line-height:1.2;flex:0 0 auto;white-space:nowrap;}
.dr-badge{display:inline-block;padding:2px 8px;border-radius:var(--tb-badge-radius, 9999px);
  font-size:11.5px;font-weight:700;letter-spacing:.2px;}


/* Shared Dispatch split-bar: Send button + Confirmed toggle (Fleet & Control tabs) */
.flt-main-dispatch-wrap{display:flex;align-items:stretch;}
.flt-main-dispatch-wrap .flt-main-dispatch-btn{flex:1;border-radius:6px 0 0 6px;}
.flt-toggle-in-dispatch{border-radius:0 6px 6px 0;padding:0 8px;display:flex;align-items:center;background:var(--tb-navy-hover, #254466);cursor:pointer;user-select:none;}
.flt-toggle-in-dispatch,.flt-toggle-in-dispatch .flt-toggle-txt{color:#FFFFFF;font-size:12px;font-weight:600;}
.flt-toggle-in-dispatch input{accent-color:#FFFFFF;margin:0 6px 0 0;cursor:pointer;}
.flt-main-dispatch-btn{appearance:none;background:var(--tb-navy, #305680);border:none;color:#FFFFFF;
  font-family:var(--tb-font, Roboto,sans-serif);font-size:var(--tb-btn-font, 12.5px);font-weight:600;line-height:1;
  padding:7px 18px;cursor:pointer;user-select:none;transition:background .15s,box-shadow .15s;text-align:center;white-space:nowrap;}
.flt-main-dispatch-btn:hover{background:var(--tb-navy-hover, #254466);box-shadow:0 2px 6px rgba(48,86,128,.3);}
.flt-main-dispatch-btn:active{background:#1C3350;}


/* ==== Armed Danger Button Unified Styles (Control & Fleet) ==== */
.dl-btn.dl-armed,
.dl-btn.dl-armed:hover,
.dl-btn.dl-armed:focus,
.dl-btn.dl-armed:active,
.flt-danger-btn.flt-danger-armed,
.flt-danger-btn.flt-danger-armed:hover,
.flt-danger-btn.flt-danger-armed:focus,
.flt-danger-btn.flt-danger-armed:active {
  background: var(--tb-danger, #B3261E) !important;
  color: #FFFFFF !important;
  border-color: var(--tb-danger, #B3261E) !important;
  outline: none !important;
  box-shadow: none !important;
  -webkit-tap-highlight-color: transparent !important;
}

.dl-btn.danger,
.flt-danger-btn {
  -webkit-tap-highlight-color: transparent !important;
  outline: none !important;
}
.dl-btn.danger:focus,
.flt-danger-btn:focus {
  outline: none !important;
}


/* Balanced 3+3 split across 2 rows for Send command presets in the 901px-1349px band */
.cfg-tiles-3x3 {
  display: grid !important;
  grid-template-columns: repeat(3, 1fr) !important;
  gap: 8px !important;
}
.cfg-tiles-3x3 .cfg-tile {
  min-width: 0 !important;
  max-width: none !important;
  flex: none !important;
  padding: 8px 8px 4px !important;
}
.cfg-tiles-col {
  display: flex !important;
  flex-direction: column !important;
  gap: 8px !important;
}

/* Send command single-line helper bar */
.dl-cmd-helper {
  font-size: 11.5px;
  color: var(--tb-slate, #64748B);
  margin-top: 4px;
  line-height: 1.35;
  min-height: 16px;
  flex: 0 0 auto;
  transition: color 0.12s ease;
  white-space: normal;
  display: block;
}
.dl-cmd-helper.active {
  color: var(--tb-navy, #305680) !important;
  font-weight: 500;
}

/* ==== Disabled Button Styles ==== */
.dl-btn:disabled,
.dl-btn[disabled] {
  opacity: 0.45 !important;
  pointer-events: none !important;
  cursor: not-allowed !important;
}


/* ==========================================================================
   Educational & Diagnostic KPI Popups (Sensor & Network Tabs)
   Single source of truth in dashboardCss. Zero inline layout styles.
   ========================================================================== */

/* Bottom-left Info Affordance Button on KPI Cards */
.kpi-info-btn {
  position: absolute;
  bottom: clamp(6px, 0.6vw, 10px);
  left: clamp(8px, 0.8vw, 14px);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: none;
  background: transparent;
  color: var(--tb-ink-muted, rgba(41, 49, 60, 0.45));
  opacity: 0.25;
  cursor: pointer;
  padding: 0;
  transition: opacity 0.2s ease, background-color 0.2s ease, color 0.2s ease;
  z-index: 2;
}

.kpi-info-btn:hover {
  opacity: 0.85;
  color: var(--tb-ink, #29313C);
  background: rgba(0, 0, 0, 0.05);
}

.kpi-info-btn .material-icons {
  font-size: 16px;
  line-height: 1;
}

@media (max-width: 600px) {
  .kpi-info-btn {
    width: 44px;
    height: 44px;
    bottom: 2px;
    left: 4px;
    opacity: 0.35;
  }
  .kpi-info-btn .material-icons {
    font-size: 18px;
  }
}

/* Popover Content Card Layout */
.popup-card {
  display: flex;
  flex-direction: column;
  padding: 24px 28px;
  min-height: 100%;
  box-sizing: border-box;
  background: #fff;
  overflow-y: auto;
  font-family: var(--tb-font, Roboto, sans-serif);
}

.popup-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--tb-border, rgba(0, 0, 0, 0.08));
  margin-bottom: 20px;
}

.title-area {
  display: flex;
  align-items: center;
  gap: 12px;
}

.header-icon {
  font-size: 32px;
  color: var(--tb-ok, #1E6C33);
}

.header-icon.network-blue {
  color: var(--tb-blue, #5469FF);
}

.header-batt-svg {
  width: 22px;
  height: 36px;
  flex-shrink: 0;
}

@media (max-width: 768px) {
  .header-batt-svg {
    width: 20px;
    height: 32px;
  }
}

.header-text h2 {
  font-size: 20px;
  font-weight: 700;
  color: var(--tb-ink, #29313C);
  line-height: 1.2;
  margin: 0;
}

.header-text span {
  font-size: 13px;
  color: var(--tb-ink-muted, rgba(41, 49, 60, 0.45));
}

.popup-grid {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 28px;
  flex: 1 1 auto;
}

.popup-grid > div {
  min-width: 0;
}

.section-title {
  font-size: 14px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--tb-ink-secondary, rgba(41, 49, 60, 0.72));
  margin-bottom: 12px;
}

.prose-block {
  font-size: 14px;
  line-height: 1.6;
  color: var(--tb-ink, #29313C);
  margin: 0 0 14px 0;
}

.analogy-box {
  background: #F8FAFC;
  border-left: 4px solid var(--tb-blue, #5469FF);
  border-radius: 0 8px 8px 0;
  padding: 12px 16px;
  font-size: 13.5px;
  line-height: 1.55;
  color: var(--tb-ink, #29313C);
  margin-bottom: 16px;
}

.analogy-label {
  font-weight: 700;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--tb-blue-dark, #1565C0);
  margin-bottom: 4px;
}

.sources-list {
  list-style: none;
  padding: 0;
  margin: 0 0 16px 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.source-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 13.5px;
  line-height: 1.45;
  color: var(--tb-ink, #29313C);
}

.source-emoji {
  font-size: 18px;
  line-height: 1.2;
  flex-shrink: 0;
}

.source-text strong {
  color: var(--tb-ink, #29313C);
}

.bands-card {
  border: 1px solid var(--tb-border, rgba(0, 0, 0, 0.08));
  border-radius: 8px;
  overflow: hidden;
  background: #fff;
}

.bands-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  text-align: left;
}

.bands-table thead {
  background: #F8FAFC;
  border-bottom: 1px solid var(--tb-border, rgba(0, 0, 0, 0.08));
}

.bands-table th {
  padding: 10px 12px;
  font-weight: 600;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: var(--tb-ink-muted, rgba(41, 49, 60, 0.45));
}

.bands-table td {
  padding: 9px 12px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.04);
  color: var(--tb-ink, #29313C);
}

.bands-table tr:last-child td {
  border-bottom: none;
}

.band-pill {
  display: inline-block;
  padding: 3px 8px;
  border-radius: var(--tb-badge-radius, 9999px);
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.3px;
  white-space: nowrap;
}

.pill-good { background: rgba(30, 108, 51, 0.12); color: var(--tb-ok, #1E6C33); }
.pill-moderate { background: rgba(249, 168, 37, 0.16); color: #9E7000; }
.pill-warn { background: rgba(235, 117, 51, 0.16); color: #D35400; }
.pill-unhealthy { background: rgba(179, 38, 30, 0.14); color: var(--tb-danger, #B3261E); }
.pill-info { background: rgba(84, 105, 255, 0.14); color: var(--tb-blue-dark, #1565C0); }
.pill-aqi-good { background: rgba(0, 153, 102, 0.16); color: #009966; }
.pill-aqi-moderate { background: rgba(245, 189, 51, 0.2); color: #9E7000; }
.pill-aqi-sensitive { background: rgba(235, 117, 51, 0.18); color: var(--tb-aqi-sensitive, #D35400); }
.pill-aqi-unhealthy { background: rgba(204, 0, 51, 0.16); color: #CC0033; }
.pill-aqi-very-unhealthy { background: rgba(102, 0, 153, 0.16); color: var(--tb-aqi-very-unhealthy, #660099); }
.pill-aqi-hazardous { background: rgba(126, 0, 35, 0.16); color: var(--tb-aqi-hazardous, #7E0023); }

.card-colour-note {
  margin-top: 10px;
  font-size: 12px;
  color: var(--tb-ink-muted, rgba(41, 49, 60, 0.45));
  font-style: italic;
  line-height: 1.4;
}

.technical-note {
  margin-top: 14px;
  padding: 10px 12px;
  border-radius: 8px;
  background: #FFFDE7;
  border-left: 3px solid #FBC02D;
  font-size: 12.5px;
  line-height: 1.5;
  color: var(--tb-ink, #29313C);
}

.technical-note strong {
  color: #7F6000;
}

.mobile-table-hint {
  display: none;
  font-size: 11px;
  font-style: italic;
  color: var(--tb-ink-muted, rgba(41, 49, 60, 0.45));
  margin-bottom: 6px;
  align-items: center;
  gap: 4px;
}

@media (max-width: 768px) {
  .popup-card {
    padding: 16px 14px 24px 14px;
  }
  .popup-grid {
    grid-template-columns: minmax(0, 1fr);
    gap: 20px;
  }
  .mobile-table-hint {
    display: flex;
  }
  .bands-card {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    width: 100%;
  }
  .bands-table {
    white-space: nowrap !important;
  }
}

/* ==== AQI phone navigation begin (aqi_phone_nav_2026-09-29.py) ==== */
/* Page navigation pills in a dashboard header (cfg-pills aq-tabs), shared by every application: each pill as wide as
   its label. The class keeps its first (AquaTrace) spelling. Appended to each application's dashboardCss by its builder. */
.aq-tabs.cfg-pills{flex:0 0 auto;gap:6px;justify-content:flex-end;flex-wrap:wrap;}
.aq-tabs.cfg-pills .flt-pill-btn{flex:0 0 auto;width:auto;max-width:none;padding:6px 14px !important;white-space:nowrap;}

/* Page tabs in a dashboard header (hdr-tabs > hdr-tab), shared by every application. Same look as the AQI Admin page
   tabs (native action buttons Sensor, Network, Control, Fleet), measured 2026-09-26 at 1920x1080: 131 x 61 px, 8 px apart,
   14 px / 500 Roboto, idle #ECEFF3 on #5A6472, active navy on white, radius 8 px on the group ends only, shadow
   0 4px 8px rgba(0,0,0,.08). Active state reuses .flt-pill-active, which the header click handlers already toggle.
   aq-tabs stays the in-card pill group (day pills, gateway pills, window switch). */
.hdr-tabs{display:flex;align-items:stretch;gap:8px;align-self:stretch;flex:0 0 auto;padding:4px 0 8px;box-sizing:border-box;}
.hdr-tabs .hdr-tab{appearance:none;border:0;margin:0;cursor:pointer;min-width:clamp(84px,6.8vw,131px);
  padding:0 clamp(10px,1vw,20px);background:#ECEFF3;color:#5A6472;font-family:var(--tb-font, Roboto, sans-serif);
  font-size:clamp(12.5px,0.73vw,14px);font-weight:500;letter-spacing:0.03125em;white-space:nowrap;border-radius:0;
  box-shadow:0 4px 8px rgba(0,0,0,.08);transition:background .12s,color .12s;}
.hdr-tabs .hdr-tab:first-child{border-radius:8px 0 0 8px;}
.hdr-tabs .hdr-tab:last-child{border-radius:0 8px 8px 0;}
.hdr-tabs .hdr-tab:hover{background:#E1E6EC;color:var(--tb-ink, #29313C);}
.hdr-tabs .hdr-tab.flt-pill-active,.hdr-tabs .hdr-tab.flt-pill-active:hover{background:var(--tb-navy, #305680) !important;color:#FFFFFF !important;}
/* Phone navigation (below 960 px), user 2026-09-29 after the bottom bar experiment (handoffs/2026-09-29_bottom_nav_experiment.md):
   the tabs become an Android style bottom bar, at most 5 slots. Tabs 1 to 4 keep a slot, the last slot is always "More".
   More opens a left drawer (also by swiping right from the left edge) holding the tabs beyond the fourth, then the account
   section (user, Profile with password change, About, Log out), because full bleed pages have no ThingsBoard user menu.
   The markup is built by shared_widgets/nav_bar.js (tbNavBar): .nav-more, .nav-scrim, .nav-panel, and a .nav-item copy of
   every tab beyond the fourth (the original keeps .nav-over and hides on phones). All of it is hidden from 960 px up.
   Header widgets then hold only the title, so their mobileHeight is 2 rows. The comment sits inside the block on purpose:
   TB 4.3's dashboardCss parser only recognises @media when the match starts at @media (a comment right before it leaked
   the rules to every width). */
.hdr-tabs .nav-more,.hdr-tabs .nav-scrim,.hdr-tabs .nav-panel,.hdr-tabs .nav-badge{display:none;}
@media (max-width: 959px) {
  gridster-item:has(.hdr-tabs),tb-widget-container:has(.hdr-tabs){z-index:200 !important;}
  gridster.mobile:has(.hdr-tabs){padding-bottom:calc(84px + env(safe-area-inset-bottom, 0px)) !important;}
  .tb-powered-by-footer{z-index:0 !important;}
  /* The token trick below only works where --tb-navy is declared on :root. The AQI master declares it on * (every element), so the
     active tab also gets the :hover selector above with a background that beats the base rule's :hover twin. */
  .hdr-tabs{--tb-navy:transparent;position:fixed;left:0;right:0;bottom:0;top:auto;z-index:300;flex-direction:row;flex-wrap:nowrap;gap:0;
    padding:0 0 env(safe-area-inset-bottom, 0px);height:auto;background:#FFFFFF;box-shadow:0 -2px 10px rgba(0,0,0,.14);align-items:stretch;}
  .hdr-tabs .hdr-tab,.hdr-tabs .nav-more{flex:1 1 0;min-width:0;width:auto;height:64px;padding:6px 2px 4px;border:0;border-radius:0;box-shadow:none;
    background:transparent !important;color:#5B6675;-webkit-text-fill-color:#5B6675;font:500 11px/1.1 var(--tb-font, Roboto, sans-serif);letter-spacing:0;
    display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;overflow:hidden;text-overflow:ellipsis;}
  .hdr-tabs .hdr-tab:first-child,.hdr-tabs .hdr-tab:last-child{border-radius:0;}
  .hdr-tabs .hdr-tab.nav-over{display:none;}
  .hdr-tabs .hdr-tab::before,.hdr-tabs .nav-more::before,.hdr-tabs .nav-item::before{font-family:"Material Icons";font-size:26px;line-height:26px;
    font-weight:400;letter-spacing:normal;text-transform:none;width:56px;height:30px;border-radius:15px;display:flex;align-items:center;justify-content:center;
    content:attr(data-icon);}
  .hdr-tabs .hdr-tab{position:relative;}
  .hdr-tabs .hdr-tab .nav-badge{display:flex;position:absolute;top:4px;left:calc(50% + 6px);min-width:18px;height:18px;padding:0 5px;box-sizing:border-box;
    align-items:center;justify-content:center;border-radius:9px;background:#B3261E;color:#FFFFFF;-webkit-text-fill-color:#FFFFFF;font:700 11px/1 var(--tb-font, Roboto, sans-serif);
    letter-spacing:0;font-variant-numeric:tabular-nums;}
  .hdr-tabs .nav-more{display:flex;cursor:pointer;}
  .hdr-tabs .nav-more::before{content:"menu";}
  .hdr-tabs .hdr-tab.flt-pill-active,.hdr-tabs .hdr-tab.flt-pill-active:hover,.hdr-tabs .nav-more.nav-on,.hdr-tabs.nav-open .nav-more{color:var(--tb-navy-ink, #305680) !important;
    -webkit-text-fill-color:var(--tb-navy-ink, #305680) !important;font-weight:600;background:transparent !important;}
  .hdr-tabs .hdr-tab.flt-pill-active::before,.hdr-tabs .nav-more.nav-on::before,.hdr-tabs.nav-open .nav-more::before{background:#DCE6F2;}
  .hdr-tabs .nav-scrim{display:block;position:fixed;inset:0;background:rgba(20,28,40,.45);z-index:310;opacity:0;pointer-events:none;transition:opacity .2s;}
  .hdr-tabs .nav-panel{display:flex;flex-direction:column;position:fixed;top:0;bottom:0;left:0;width:min(300px,84vw);overflow-y:auto;background:#FFFFFF;
    z-index:320;transform:translateX(-100%);transition:transform .22s ease;padding:20px 12px calc(16px + env(safe-area-inset-bottom, 0px));box-sizing:border-box;
    font-family:var(--tb-font, Roboto, sans-serif);}
  .hdr-tabs.nav-open .nav-scrim{opacity:1;pointer-events:auto;}
  .hdr-tabs.nav-open .nav-panel{transform:none;box-shadow:4px 0 16px rgba(0,0,0,.2);}
  .nav-panel .nav-head{margin:4px 12px 12px;font:600 12px/1 var(--tb-font, Roboto, sans-serif);letter-spacing:.06em;text-transform:uppercase;color:#7A8594;}
  .nav-panel .nav-sep{height:1px;background:#E3E8EE;margin:10px 4px;flex:0 0 auto;}
  .nav-panel .nav-user{margin:2px 12px 8px;font-size:13px;color:#5B6675;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
  .nav-panel .nav-item{appearance:none;border:0;margin:0;cursor:pointer;flex:0 0 auto;width:100%;height:52px;padding:0 12px;display:flex;align-items:center;gap:14px;
    background:transparent !important;color:#29313C;-webkit-text-fill-color:#29313C;font:500 15px/1 var(--tb-font, Roboto, sans-serif);letter-spacing:0;
    border-radius:26px;text-align:left;box-shadow:none;}
  .nav-panel .nav-item::before{width:auto;height:auto;border-radius:0;font-size:24px;line-height:24px;}
  .nav-panel .nav-item.flt-pill-active{background:#DCE6F2 !important;color:#305680;-webkit-text-fill-color:#305680;font-weight:600;}
  .nav-panel .nav-item.nav-danger,.nav-panel .nav-item.nav-danger::before{color:#B3261E;-webkit-text-fill-color:#B3261E;}
  .nav-panel .nav-fold{display:none;flex:0 0 auto;margin:2px 12px 6px;padding:10px 12px;border-radius:12px;background:#F4F6F9;font-size:13px;line-height:1.45;color:#3A4451;}
  .nav-panel .nav-fold.nav-shown{display:block;}
  .nav-panel .nav-fold input{width:100%;box-sizing:border-box;margin:0 0 8px;padding:10px;border:1px solid #C9D1DB;border-radius:8px;font:14px var(--tb-font, Roboto, sans-serif);background:#FFFFFF;color:#29313C;}
  .nav-panel .nav-fold .nav-save{width:100%;height:44px;border:0;border-radius:8px;background:#305680;color:#FFFFFF;-webkit-text-fill-color:#FFFFFF;font:500 14px var(--tb-font, Roboto, sans-serif);cursor:pointer;}
  .nav-panel .nav-fold .nav-msg{margin:0 0 8px;font-size:12.5px;color:#B3261E;min-height:0;}
  .nav-panel .nav-fold .nav-msg.nav-ok{color:#1E7B45;}
}


@media (min-width: 960px) {
  /* the phone bar has nothing to show above 960 px */
  gridster-item:has(#aqiNav) { display: none !important; }
}
@media (max-width: 959px) {
  /* the bar replaces the native Map / Sensor / Network / Control / Fleet buttons and takes no room in the flow */
  gridster.mobile:has(#aqiNav) gridster-item:has(tb-widget-button) { display: none !important; }
  gridster.mobile:has(#aqiNav) gridster-item:has(#aqiNav) { height: 0 !important; min-height: 0 !important; overflow: visible; z-index: 200; }
}
/* ==== AQI phone navigation end ==== */
